function makeClass(name,capacity=40,meta={}){return {name,capacity,available:capacity,...meta}}
function makeLevel(name,classes){return {name,classes:classes.map(c=>typeof c==='string'?makeClass(c):c)}}
function subjectsForType(type){return type==='Primary School'?PRIMARY_SUBJECTS:SECONDARY_SUBJECTS}
function defaultLevels(){return [makeLevel('School programmes',CLASS_OPTIONS.map(c=>makeClass(c.name,c.capacity,{programId:c.programId,level:c.level,category:c.category,fee:c.fee,monthly:c.monthly,subjects:c.subjects})))]}
function flattenClasses(s){return (s?.levels||[]).flatMap(l=>l.classes||[])}
function levelOfClass(s,cls){return flattenClasses(s).find(c=>c.name===cls)?.level||cls}
function programForClass(s,cls){const c=flattenClasses(s).find(x=>x.name===cls);return PROGRAMS.find(p=>p.id===c?.programId)||PROGRAMS.find(p=>p.label===cls)||null}
function schoolSubjects(s){return s?.subjects?.length?s.subjects:SECONDARY_SUBJECTS}
function subjectsForClass(s,cls){return programForClass(s,cls)?.subjects||schoolSubjects(s)}
function totalSpaces(s){return flattenClasses(s).reduce((a,c)=>a+Number(c.available||0),0)}
function avgStudent(st){const a=(st.assessments||[]).map(x=>Number(x.mark)).filter(Number.isFinite);return a.length?Math.round(a.reduce((x,y)=>x+y,0)/a.length):0}
function aggregate(st){const subjects=[...new Set((st.assessments||[]).map(a=>a.subject))];if(!subjects.length)return 0;return Math.round(subjects.reduce((sum,sub)=>{const a=(st.assessments||[]).filter(x=>x.subject===sub);return sum+(a.length?a[a.length-1].mark:0)},0)/subjects.length)}
